<?php $e = static fn (mixed $v): string => App\Core\View::e($v); $csrf = App\Core\Security::csrfToken(); ?>
<section class="page-stack"><div class="section-heading"><div><p class="eyebrow"><?= $e($match['championship_name']) ?></p><h1>Operadores da partida</h1><p><?= $e($match['home_team_name']) ?> x <?= $e($match['away_team_name']) ?></p></div><a class="button secondary" href="<?= $e(App\Core\Config::url('/admin/partidas/' . $match['id'])) ?>">Voltar</a></div><?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?><article class="panel"><form method="post" class="form-row" action="<?= $e(App\Core\Config::url('/admin/partidas/' . $match['id'] . '/operadores')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Operador <select name="operator_id" required><option value="">Selecione</option><?php foreach ($operators as $operator): ?><option value="<?= (int) $operator['id'] ?>"><?= $e($operator['name']) ?> (<?= $e($operator['email']) ?>)</option><?php endforeach; ?></select></label><button type="submit">Atribuir</button></form></article><article class="panel"><h2>Atribuições ativas</h2><?php if ($assigned === []): ?><p>Nenhum operador atribuído.</p><?php else: ?><ul><?php foreach ($assigned as $assignment): ?><li><?= $e($assignment['name']) ?> — <?= $e($assignment['email']) ?></li><?php endforeach; ?></ul><?php endif; ?></article></section>
